-- ref.Ships: 1 rows
MERGE ref.Ships AS t
USING (VALUES
  (N'sun-princess', N'Sun Princess', N'Sphere class', 17, 177882, 4300, N'America/New_York', CAST(N'{"id":"sun-princess","name":"Sun Princess","className":"Sphere class","entered":2024,"tonnage":177882,"length":"1,133 ft","guests":4300,"crew":1600,"staterooms":2157,"accessibleStaterooms":51,"connectingStaterooms":100,"decks":17,"sanctuaryStaterooms":215,"intro":"Princess' AS NVARCHAR(MAX)) + NCHAR(8217) + N's newest ship, built around the Piazza, a three-level gathering place under a glass Sphere, and the Dome, a glass-roofed pool by day and a theatre by night.","highlights":[{"title":"The Piazza","body":"Three levels of caf' + NCHAR(233) + N's, bars and live music under the Sphere, with game shows and roaming performers."},{"title":"The Dome","body":"A glass dome on decks 17 and 18: a pool by day, acrobatic theatre at night, and a dance party late."},{"title":"Princess Arena","body":"The main show venue, seating about 900, set up three ways for different productions."},{"title":"Dining included","body":"Three dining rooms, the Eatery buffet, the Americana Diner, casual grills and pizza, plus 24-hour room service."},{"title":"Specialty dining","body":"Steakhouse, Italian, seafood, sushi, teppanyaki and a prix fixe with sea views, at an extra charge unless your package covers them."},{"title":"Kids and teens","body":"Firefly Park (3' + NCHAR(8211) + N'7), Neon Grove (8' + NCHAR(8211) + N'12) and The Underground (13' + NCHAR(8211) + N'17), all on decks 6 and 7."},{"title":"The Sanctuary","body":"An adults-only retreat on deck 18 for guests in the Sanctuary Collection of 215 staterooms."}],"accessibility":["51 accessible staterooms, with roll-in showers and wider doors.","Six elevator banks with touchscreens that assign a car; interactive deck maps beside each bank.","Wheelchair-accessible seating in the Arena, the Piazza and the main dining rooms.","Belize City is a tender port: the boats have steps, and mobility help there is limited. Ask Guest Services before you book a shore day.","Tell Princess about a wheelchair, scooter or other need at least 30 days before you sail."],"otherShips":[{"name":"Star Princess","note":"Sun Princess' + NCHAR(8217) + N's sister ship, also Sphere class.","guests":4300,"entered":2025},{"name":"Sky Princess","note":"Grand class, known for the SeaWalk over the side of the ship.","guests":3660,"entered":2019},{"name":"Enchanted Princess","note":"Royal class, with a larger spa and plenty of casual dining.","guests":3660,"entered":2020}]}')
) AS s ([Id], [Name], [Class], [Decks], [Tonnage], [Capacity], [HomeZone], [ProfileJson])
ON t.[Id] = s.[Id]
WHEN MATCHED THEN UPDATE SET t.[Name] = s.[Name], t.[Class] = s.[Class], t.[Decks] = s.[Decks], t.[Tonnage] = s.[Tonnage], t.[Capacity] = s.[Capacity], t.[HomeZone] = s.[HomeZone], t.[ProfileJson] = s.[ProfileJson]
WHEN NOT MATCHED THEN INSERT ([Id], [Name], [Class], [Decks], [Tonnage], [Capacity], [HomeZone], [ProfileJson]) VALUES (s.[Id], s.[Name], s.[Class], s.[Decks], s.[Tonnage], s.[Capacity], s.[HomeZone], s.[ProfileJson]);
GO

